+/** Dispatch a target-specific relation event to pair tracking modifiers. */
+export function setPairTracking(
+    world: World,
+    entity: Entity,
+    trait: Trait,
+    target: Entity,
+    eventType: 'add' | 'remove' | 'change'
+) {
+    const data = getTraitInstance(world[$internal].traitInstances, trait);
+    if (!data) return;
+
+    const { generationId, bitflag } = data;
+    const key = `${trait.id}:${target}`;
+    const eid = getEntityId(entity);
+
+    for (const eventsByEntity of world[$internal].pairTrackingEvents.values()) {
+        let events = eventsByEntity.get(eid);
+        if (!events) eventsByEntity.set(eid, (events = new Map()));
+        events.set(key, eventType);
+    }
+
+    for (const query of data.trackingQueries) {
+        let tracksPair = false;
+        for (const group of query.trackingGroups) {
+            if (!group.pairs?.some((pair) => pair[$internal].relation[$internal].trait === trait)) continue;
+            tracksPair = true;
+            let events = group.pairTrackers!.get(eid);
+            if (!events) group.pairTrackers!.set(eid, (events = new Map()));
+            events.set(key, eventType);
+        }
+        if (!tracksPair) continue;
+
+        const match =
+            query.relationFilters && query.relationFilters.length > 0
+                ? checkQueryTrackingWithRelations(world, query, entity, eventType, generationId, bitflag)
+                : query.checkTracking(world, entity, eventType, generationId, bitflag);
+        if (match) query.add(entity);
+        else query.remove(world, entity);
+    }
